function restorePrototype(){try{const saved=JSON.parse(localStorage.getItem('scope-studio-v1'));if(!saved)return INITIAL;const migrate=value=>Array.isArray(value)?value.map(migrate):value&&typeof value==='object'?Object.fromEntries(Object.entries(value).map(([key,v])=>[key,migrate(v)])):typeof value==='string'?value.replace(/Savannah\s+Willi(?:ams)/g,'Savannah Copeland'):value;const data=migrate(saved);if(!data.timeRecords)data.timeRecords=CLOCKIFY_TIME_RECORDS.map(r=>({...r,...(data.unmatched&&r.id==='CF-206'?{projectId:1}:data.unmatched&&r.id==='CF-207'?{projectId:2}:{}),hours:r.projectId&&r.id<'CF-206'?(data.projects?.find(p=>p.id===r.projectId)?.hours??r.hours):r.hours}));if(data.requests)data.requests=data.requests.map(r=>r.sender==='Savannah Copeland'?{...r,initials:'SC'}:r);return {...INITIAL,...data}}catch{return INITIAL}}
const NAV=[['Overview',LayoutGrid],['Inbox',Inbox],['Projects',Layers],['Team',Users],['Billing',Receipt],['Settings',Settings]];
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);
const day=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});
function IconButton({icon:Icon,label,onClick,children,...props}){return <button className="icon-btn" title={label} aria-label={label} onClick={onClick} {...props}><Icon size={17}/>{children}</button>}
function Button({children,onClick,variant='',...props}){return <button className={'btn '+variant} onClick={onClick} {...props}>{children}</button>}
function Avatar({member,size='',...props}){return <span className={'avatar '+member.color+' '+size} title={member.name} {...props}>{member.initials}</span>}
function Status({children}){return <span className={'status '+(children==='In production'||children==='Ready'||children==='Approved'?'green':children==='In review'||children==='Needs clarification'?'orange':children==='Scheduled'?'gray':'purple')}><i/>{children}</span>}
