 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),3500);return()=>clearTimeout(t)},[toast]);
 useEffect(()=>{if(!modal||typeof document==='undefined')return;const previous=document.activeElement;const overflow=document.body.style.overflow;document.body.style.overflow='hidden';const dialog=document.querySelector('[role="dialog"]');const selectors='button:not([disabled]),a[href],input,select,textarea,[tabindex="0"]';const controls=()=>Array.from(dialog?.querySelectorAll(selectors)||[]);controls()[0]?.focus();const trap=e=>{if(e.key!=='Tab')return;const items=controls();const first=items[0],last=items.at(-1);if(!first)return;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}};document.addEventListener('keydown',trap);return()=>{document.body.style.overflow=overflow;document.removeEventListener('keydown',trap);previous?.focus?.()}},[modal?.type]);
