 const exportInvoice=()=>{const lines=[['Invoice',invoice.id],['Client',invoice.client],['Period',period],['Currency','USD'],['Draft status',invoice.status],['Terms',invoice.terms||'Net 30'],['Notes',invoice.note||''],['Handoff','Manual CSV export to existing invoicing process'],['Delivery status','Not sent'],[],['Description','Hours','Rate','Amount'],...invoice.lines.map(l=>[l.description,l.hours,invoice.rate,l.hours*invoice.rate]),[],['Total',invoice.lines.reduce((s,l)=>s+l.hours*invoice.rate,0)]];const csv=lines.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download=invoice.id+'.csv';a.click();URL.revokeObjectURL(url);notify('CSV exported for manual handoff to your existing invoicing process. No invoice was sent.');};
